#!/usr/bin/env python3
import urllib.request
import json
import http.cookiejar

BASE = "http://170.106.171.59:8080/careconnected"
NONCE = "b96fe1729b"
COOKIE_FILE = "/tmp/wp_session.txt"

jar = http.cookiejar.MozillaCookieJar(COOKIE_FILE)
jar.load(ignore_discard=True, ignore_expires=True)
opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))

def update_page(page_id, title, content):
    url = f"{BASE}/wp-json/wp/v2/pages/{page_id}"
    payload = json.dumps({"title": title, "content": content, "status": "publish"}).encode()
    req = urllib.request.Request(url, data=payload, method="POST")
    req.add_header("X-WP-Nonce", NONCE)
    req.add_header("Content-Type", "application/json")
    try:
        resp = opener.open(req)
        body = json.loads(resp.read())
        print(f"OK  page {page_id}: {title}")
    except urllib.error.HTTPError as e:
        print(f"ERR page {page_id}: {e.code} {e.read()[:300]}")

def hero(h1, subtitle):
    return (
        f'<!-- wp:cover {{"customGradient":"linear-gradient(135deg,rgb(15,118,110) 0%,rgb(13,148,136) 100%)","isDark":true,"minHeight":200,"minHeightUnit":"px","align":"full"}} -->'
        f'<div class="wp-block-cover alignfull is-dark" style="min-height:200px"><div class="wp-block-cover__inner-container">'
        f'<!-- wp:heading {{"level":1,"textColor":"white","style":{{"typography":{{"fontWeight":"800","fontSize":"2.25rem"}}}}}} -->'
        f'<h1 class="wp-block-heading has-white-color has-text-color">{h1}</h1><!-- /wp:heading -->'
        f'<!-- wp:paragraph {{"style":{{"color":{{"text":"rgba(255,255,255,0.85)"}}}}}} -->'
        f'<p style="color:rgba(255,255,255,0.85)">{subtitle}</p><!-- /wp:paragraph -->'
        f'</div></div><!-- /wp:cover -->'
        f'\n<!-- wp:spacer {{"height":"2rem"}} --><div style="height:2rem" class="wp-block-spacer"></div><!-- /wp:spacer -->\n'
    )

